use std::io::{Read, Write};

fn main() {
    let mut number = false;
    let mut files = Vec::new();
    for a in std::env::args().skip(1) {
        if a == "-n" {
            number = true;
        } else {
            files.push(a);
        }
    }
    let mut out: Vec<u8> = Vec::new();
    let mut status = 0;
    let mut counter = 0u64;
    let mut process = |data: &[u8], out: &mut Vec<u8>| {
        if !number {
            out.extend_from_slice(data);
            return;
        }
        let mut rest = data;
        while !rest.is_empty() {
            let (line, next) = match rest.iter().position(|&b| b == b'\n') {
                Some(p) => (&rest[..p], &rest[p + 1..]),
                None => (rest, &rest[rest.len()..]),
            };
            counter += 1;
            out.extend_from_slice(format!("{:6}\t", counter).as_bytes());
            out.extend_from_slice(line);
            out.push(b'\n');
            rest = next;
        }
    };
    if files.is_empty() {
        let mut d = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut d);
        process(&d, &mut out);
    } else {
        for f in &files {
            match std::fs::read(f) {
                Ok(d) => process(&d, &mut out),
                Err(_) => {
                    out.extend_from_slice(format!("cat: {}: No such file\n", f).as_bytes());
                    status = 1;
                }
            }
        }
    }
    let so = std::io::stdout();
    let mut l = so.lock();
    let _ = l.write_all(&out);
    let _ = l.flush();
    std::process::exit(status);
}

